import json, re, decimal
from pathlib import Path

analysis_path = Path('/root/infusion_batch_analysis.json')
summary_path = Path('/root/infusion_batch_summary.md')

with analysis_path.open() as f:
    data = json.load(f)

errors=[]
for key in ['assumptions','therapies','totals','recommendation']:
    if key not in data:
        errors.append(f'missing top-level key {key}')
if 'recommendation' in data:
    for key in ['decision','justification']:
        if key not in data['recommendation']:
            errors.append(f'missing recommendation key {key}')

codes=[t.get('therapy_code') for t in data.get('therapies', [])]
if codes != sorted(codes):
    errors.append(f'therapies not sorted: {codes}')

if data.get('recommendation',{}).get('decision') not in {'move_to_14_day','keep_7_day'}:
    errors.append('invalid decision slug')

# Check numeric currency fields have at most 2 decimal places.
currency_key_markers = ('usd', 'cost', 'revenue', 'margin', 'payment')
def check_currency(obj, path=''):
    if isinstance(obj, dict):
        for k,v in obj.items():
            p=f'{path}.{k}' if path else k
            if isinstance(v, (int,float)) and any(m in k for m in currency_key_markers):
                d=decimal.Decimal(str(v))
                if -d.as_tuple().exponent > 2:
                    errors.append(f'{p} has >2 decimals: {v}')
            check_currency(v, p)
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            check_currency(v, f'{path}[{i}]')
check_currency(data)

summary = summary_path.read_text()
nonempty=[line for line in summary.splitlines() if line.strip()]
if not (4 <= len(nonempty) <= 8):
    errors.append(f'markdown non-empty line count {len(nonempty)} outside 4-8')
# Money amounts in markdown should contain commas where thousands are present.
for amount in re.findall(r'\$(-?\d[\d,]*\.\d{2})', summary):
    integer = amount.split('.')[0].lstrip('-')
    if len(integer.replace(',','')) >= 4 and ',' not in integer:
        errors.append(f'markdown amount lacks thousands comma: {amount}')

if errors:
    print('VALIDATION FAILED')
    for e in errors: print('-', e)
    raise SystemExit(1)
print('VALIDATION PASSED')
print('Top-level keys:', sorted(data.keys()))
print('Therapy codes:', codes)
print('Markdown non-empty lines:', len(nonempty))
print('Decision:', data['recommendation']['decision'])
